/* v1.3.21 calendar status + session history */
.calendar-legend i.upcoming{background:#eab308!important;box-shadow:0 0 0 3px rgba(234,179,8,.12)}
.calendar-event.upcoming span{background:#eab308!important}
.history-match-list{display:grid;gap:12px}.history-match{display:grid;gap:8px}.history-match-head{display:flex;align-items:flex-start;justify-content:space-between;gap:10px}.history-match-head b{font-size:12px}.history-duration{white-space:nowrap}.schedule-tap{text-decoration:none;color:inherit}
@media(max-width:420px){.schedule-actions.three{grid-template-columns:1fr}.history-match-head{align-items:center}}
